{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "mark": "bar",
  "encoding": {
    "y": {"field": "SubCategory", "type": "nominal"},
    "x": {"field": "Total Sales", "type": "quantitative"}
  }
}

{
  "encoding": {"x": "…shared…", "y": "…shared…"},
  "layer": [
    {"mark": "rect", "encoding": {"color": "…"}},
    {"mark": "text", "encoding": {"text": "…"}}
  ]
}

{
  "color": {
    "condition": {"test": "datum['Total Sales'] > 100000", "value": "white"},
    "value": "#333"
  }
}

{
  "opacity": {"condition": {"test": "datum.__selected__ == 'off'", "value": 0.25}, "value": 1}
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "mark": "rect",
  "encoding": {
    "x": {"field": "Region", "type": "nominal"},
    "y": {"field": "SubCategory", "type": "nominal"}
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "encoding": {
    "x": {
      "field": "Region",
      "type": "nominal",
      "axis": {"orient": "top", "title": null, "labelAngle": 0}
    },
    "y": {"field": "SubCategory", "type": "nominal", "title": null}
  },
  "layer": [
    {
      "mark": {"type": "rect", "stroke": "white", "strokeWidth": 1.5},
      "encoding": {
        "color": {
          "field": "Total Sales",
          "type": "quantitative",
          "scale": {"scheme": "blues"}
        }
      }
    },
    {
      "mark": {"type": "text", "fontSize": 11},
      "encoding": {"text": {"field": "Total Sales", "type": "quantitative", "format": ",.0f"}}
    }
  ]
}

{
  "condition": {"test": "datum['Total Sales'] > datum.maxSales * 0.55", "value": "white"},
  "value": "#333"
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "transform": [{"joinaggregate": [{"op": "max", "field": "Total Sales", "as": "maxSales"}]}],
  "encoding": {
    "x": {
      "field": "Region",
      "type": "nominal",
      "axis": {"orient": "top", "title": null, "labelAngle": 0}
    },
    "y": {"field": "SubCategory", "type": "nominal", "title": null}
  },
  "layer": [
    {
      "mark": {"type": "rect", "stroke": "white", "strokeWidth": 1.5},
      "encoding": {
        "color": {
          "field": "Total Sales__highlight",
          "type": "quantitative",
          "title": "Sales",
          "scale": {"scheme": "blues"},
          "legend": {"format": "~s"}
        },
        "opacity": {
          "condition": {"test": "datum.__selected__ == 'off'", "value": 0.25},
          "value": 1
        },
        "tooltip": [
          {"field": "Region"},
          {"field": "SubCategory"},
          {"field": "Total Sales", "format": ",.0f"},
          {
            "field": "Total Sales__highlight",
            "title": "Highlighted",
            "format": ",.0f"
          }
        ]
      }
    },
    {
      "mark": {"type": "text", "fontSize": 11},
      "encoding": {
        "text": {
          "field": "Total Sales__highlight",
          "type": "quantitative",
          "format": ",.0f"
        },
        "color": {
          "condition": {
            "test": "datum['Total Sales__highlight'] > datum.maxSales * 0.55",
            "value": "white"
          },
          "value": "#333"
        },
        "opacity": {
          "condition": {"test": "datum.__selected__ == 'off'", "value": 0.25},
          "value": 1
        }
      }
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "mark": "bar",
  "encoding": {
    "x": {"field": "YearMonth", "type": "ordinal"},
    "y": {"field": "Total Sales", "type": "quantitative"}
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "encoding": {"x": {"field": "YearMonth", "type": "ordinal"}},
  "layer": [
    {
      "mark": "bar",
      "encoding": {"y": {"field": "Total Sales", "type": "quantitative"}}
    },
    {
      "mark": {"type": "line", "color": "#f28e2b"},
      "encoding": {"y": {"field": "Profit Ratio", "type": "quantitative"}}
    }
  ]
}

{
  "mark": {"type": "bar", "color": "#4e79a7"},
  "encoding": {
    "y": {
      "field": "Total Sales",
      "type": "quantitative",
      "title": "Sales",
      "axis": {"titleColor": "#4e79a7", "format": "~s"}
    }
  }
}

{
  "mark": {"type": "line", "color": "#f28e2b"},
  "encoding": {
    "y": {
      "field": "Profit Ratio",
      "type": "quantitative",
      "title": "Profit ratio",
      "axis": {"format": ".0%", "titleColor": "#f28e2b", "grid": false}
    }
  }
}

{
  "field": "YearMonth",
  "type": "ordinal",
  "title": null,
  "axis": {
    "labelAngle": -45,
    "labelExpr": "indexof(['01','04','07','10'], slice(datum.value, 5)) >= 0 ? datum.value : ''"
  }
}

{
  "type": "line",
  "color": "#f28e2b",
  "strokeWidth": 2.5,
  "point": {"filled": true, "color": "#f28e2b"}
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "encoding": {
    "x": {
      "field": "YearMonth",
      "type": "ordinal",
      "title": null,
      "axis": {
        "labelAngle": -45,
        "labelExpr": "indexof(['01','04','07','10'], slice(datum.value, 5)) >= 0 ? datum.value : ''"
      }
    }
  },
  "layer": [
    {
      "layer": [
        {
          "mark": {"type": "bar", "color": "#4e79a7", "opacity": 0.3},
          "encoding": {
            "y": {
              "field": "Total Sales",
              "type": "quantitative",
              "title": "Sales",
              "axis": {"titleColor": "#4e79a7", "format": "~s"}
            }
          }
        },
        {
          "mark": {"type": "bar", "color": "#4e79a7"},
          "encoding": {
            "y": {"field": "Total Sales__highlight", "type": "quantitative"},
            "opacity": {
              "condition": {"test": "datum.__selected__ == 'off'", "value": 0},
              "value": 1
            },
            "tooltip": [
              {"field": "YearMonth", "title": "Month"},
              {"field": "Total Sales", "format": ",.0f"},
              {"field": "Profit Ratio", "format": ".1%"}
            ]
          }
        }
      ]
    },
    {
      "mark": {
        "type": "line",
        "color": "#f28e2b",
        "strokeWidth": 2.5,
        "point": {"filled": true, "color": "#f28e2b"}
      },
      "encoding": {
        "y": {
          "field": "Profit Ratio",
          "type": "quantitative",
          "title": "Profit ratio",
          "axis": {"format": ".0%", "titleColor": "#f28e2b", "grid": false}
        },
        "tooltip": [
          {"field": "YearMonth", "title": "Month"},
          {"field": "Profit Ratio", "format": ".1%"}
        ]
      }
    }
  ],
  "resolve": {"scale": {"y": "independent"}}
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "mark": "bar",
  "encoding": {
    "y": {"field": "Category", "type": "nominal", "title": null},
    "x": {"field": "Total Sales", "type": "quantitative"}
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "encoding": {"y": {"field": "Category", "type": "nominal", "title": null}},
  "layer": [
    {
      "mark": {"type": "bar", "color": "#4e79a7", "size": 12},
      "encoding": {"x": {"field": "Total Sales", "type": "quantitative"}}
    },
    {
      "mark": {"type": "tick", "color": "black", "thickness": 3, "size": 28},
      "encoding": {"x": {"field": "Total Target", "type": "quantitative"}}
    }
  ]
}

[
  {"calculate": "datum['Total Target'] * 0.6", "as": "B60"},
  {"calculate": "datum['Total Target'] * 0.8", "as": "B80"},
  {"calculate": "datum['Total Target'] * 1.2", "as": "B120"}
]

{
  "mark": {"type": "bar", "color": "#e6e6e6", "size": 30},
  "encoding": {
    "x": {
      "field": "B120",
      "type": "quantitative",
      "title": "Sales vs target",
      "axis": {"format": "~s"}
    }
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "transform": [
    {"calculate": "datum['Total Target'] * 0.6", "as": "B60"},
    {"calculate": "datum['Total Target'] * 0.8", "as": "B80"},
    {"calculate": "datum['Total Target'] * 1.2", "as": "B120"}
  ],
  "encoding": {"y": {"field": "Category", "type": "nominal", "title": null}},
  "layer": [
    {
      "mark": {"type": "bar", "color": "#e6e6e6", "size": 30},
      "encoding": {
        "x": {
          "field": "B120",
          "type": "quantitative",
          "title": "Sales vs target",
          "axis": {"format": "~s"}
        }
      }
    },
    {
      "mark": {"type": "bar", "color": "#cfcfcf", "size": 30},
      "encoding": {"x": {"field": "Total Target", "type": "quantitative"}}
    },
    {
      "mark": {"type": "bar", "color": "#b5b5b5", "size": 30},
      "encoding": {"x": {"field": "B80", "type": "quantitative"}}
    },
    {
      "mark": {"type": "bar", "color": "#9e9e9e", "size": 30},
      "encoding": {"x": {"field": "B60", "type": "quantitative"}}
    },
    {
      "mark": {"type": "bar", "color": "#4e79a7", "size": 12, "opacity": 0.35},
      "encoding": {"x": {"field": "Total Sales", "type": "quantitative"}}
    },
    {
      "mark": {"type": "bar", "color": "#4e79a7", "size": 12},
      "encoding": {
        "x": {"field": "Total Sales__highlight", "type": "quantitative"},
        "opacity": {
          "condition": {"test": "datum.__selected__ == 'off'", "value": 0},
          "value": 1
        },
        "tooltip": [
          {"field": "Category"},
          {"field": "Total Sales", "format": ",.0f"},
          {"field": "Total Target", "format": ",.0f"},
          {"field": "Attainment %", "format": ".1%"}
        ]
      }
    },
    {
      "mark": {"type": "tick", "color": "black", "thickness": 3, "size": 28},
      "encoding": {"x": {"field": "Total Target", "type": "quantitative"}}
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "mark": "point",
  "encoding": {
    "x": {"field": "Total Sales", "type": "quantitative"},
    "y": {"field": "Total Profit", "type": "quantitative"}
  }
}

{
  "mark": {"type": "line", "color": "#777", "strokeDash": [4, 3]},
  "transform": [{"regression": "Total Profit", "on": "Total Sales"}],
  "encoding": {
    "x": {"field": "Total Sales", "type": "quantitative"},
    "y": {"field": "Total Profit", "type": "quantitative"}
  }
}

{
  "mark": {"type": "rule", "color": "#bbb"},
  "encoding": {"x": {"aggregate": "mean", "field": "Total Sales", "type": "quantitative"}}
}

{
  "mark": {"type": "rule", "color": "#bbb"},
  "encoding": {"y": {"aggregate": "mean", "field": "Total Profit", "type": "quantitative"}}
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "layer": [
    {
      "mark": {"type": "point", "filled": true, "size": 110},
      "encoding": {
        "x": {
          "field": "Total Sales",
          "type": "quantitative",
          "title": "Sales",
          "axis": {"format": "~s"}
        },
        "y": {
          "field": "Total Profit",
          "type": "quantitative",
          "title": "Profit",
          "axis": {"format": "~s"}
        },
        "color": {"field": "Category", "type": "nominal"},
        "shape": {"field": "Region", "type": "nominal"},
        "opacity": {
          "condition": [
            {"test": "datum.__selected__ == 'off'", "value": 0.25},
            {
              "test": "datum['Total Sales__highlightStatus'] == 'off'",
              "value": 0.25
            }
          ],
          "value": 0.9
        },
        "tooltip": [
          {"field": "SubCategory"},
          {"field": "Region"},
          {"field": "Total Sales", "format": ",.0f"},
          {"field": "Total Profit", "format": ",.0f"}
        ]
      }
    },
    {
      "mark": {"type": "line", "color": "#777", "strokeDash": [4, 3]},
      "transform": [{"regression": "Total Profit", "on": "Total Sales"}],
      "encoding": {
        "x": {"field": "Total Sales", "type": "quantitative"},
        "y": {"field": "Total Profit", "type": "quantitative"}
      }
    },
    {
      "mark": {"type": "rule", "color": "#bbb"},
      "encoding": {"x": {"aggregate": "mean", "field": "Total Sales", "type": "quantitative"}}
    },
    {
      "mark": {"type": "rule", "color": "#bbb"},
      "encoding": {"y": {"aggregate": "mean", "field": "Total Profit", "type": "quantitative"}}
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "mark": {"type": "bar", "color": "#c7d6e8", "size": 22},
  "encoding": {
    "y": {"field": "SubCategory", "type": "nominal", "title": null},
    "x": {"field": "Total Target", "type": "quantitative"}
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "encoding": {"y": {"field": "SubCategory", "type": "nominal", "title": null}},
  "layer": [
    {
      "mark": {"type": "bar", "color": "#c7d6e8", "size": 22},
      "encoding": {
        "x": {"field": "Total Target", "type": "quantitative", "title": "Sales / Target"}
      }
    },
    {
      "mark": {"type": "bar", "color": "#4e79a7", "size": 10},
      "encoding": {"x": {"field": "Total Sales", "type": "quantitative"}}
    }
  ]
}

[
  {
    "calculate": "datum['Total Sales'] >= datum['Total Target'] ? 'Met' : 'Missed'",
    "as": "Status"
  }
]

{
  "field": "Status",
  "type": "nominal",
  "title": null,
  "scale": {"domain": ["Met", "Missed"], "range": ["#4e79a7", "#e15759"]}
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"name": "dataset"},
  "transform": [
    {
      "calculate": "datum['Total Sales'] >= datum['Total Target'] ? 'Met' : 'Missed'",
      "as": "Status"
    }
  ],
  "encoding": {"y": {"field": "SubCategory", "type": "nominal", "sort": "-x", "title": null}},
  "layer": [
    {
      "mark": {"type": "bar", "color": "#c7d6e8", "size": 22},
      "encoding": {
        "x": {
          "field": "Total Target",
          "type": "quantitative",
          "title": "Sales / Target",
          "axis": {"format": "~s"}
        }
      }
    },
    {
      "mark": {"type": "bar", "size": 10},
      "encoding": {
        "x": {"field": "Total Sales__highlight", "type": "quantitative"},
        "color": {
          "field": "Status",
          "type": "nominal",
          "title": null,
          "scale": {"domain": ["Met", "Missed"], "range": ["#4e79a7", "#e15759"]}
        },
        "opacity": {
          "condition": {"test": "datum.__selected__ == 'off'", "value": 0.25},
          "value": 1
        },
        "tooltip": [
          {"field": "SubCategory"},
          {"field": "Total Sales", "format": ",.0f"},
          {"field": "Total Target", "format": ",.0f"},
          {"field": "Attainment %", "format": ".1%"}
        ]
      }
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "data": [
    {"name": "dataset"},
    {
      "name": "tree",
      "source": "dataset",
      "transform": [
        {"type": "formula", "expr": "datum.SubCategory", "as": "id"},
        {"type": "formula", "expr": "'root'", "as": "parent"}
      ]
    },
    {"name": "rootNode", "values": [{"id": "root", "parent": null}]},
    {
      "name": "nodes",
      "source": ["rootNode", "tree"],
      "transform": [
        {"type": "stratify", "key": "id", "parentKey": "parent"},
        {
          "type": "pack",
          "field": "Total Sales",
          "sort": {"field": "value", "order": "descending"},
          "size": [{"signal": "width"}, {"signal": "height"}],
          "padding": 4
        }
      ]
    }
  ],
  "marks": [
    {
      "type": "symbol",
      "from": {"data": "nodes"},
      "encode": {
        "update": {
          "x": {"field": "x"},
          "y": {"field": "y"},
          "shape": {"value": "circle"},
          "size": {"signal": "4 * datum.r * datum.r"},
          "fill": {"value": "#4e79a7"},
          "stroke": {"value": "white"}
        }
      }
    }
  ]
}

[
  {
    "name": "color",
    "type": "ordinal",
    "domain": {"data": "dataset", "field": "Category"},
    "range": {"scheme": "tableau10"}
  }
]

{
  "type": "text",
  "from": {"data": "nodes"},
  "encode": {
    "update": {
      "x": {"field": "x"},
      "y": {"field": "y"},
      "align": {"value": "center"},
      "baseline": {"value": "middle"},
      "fill": {"value": "white"},
      "text": {"signal": "datum.r < 16 ? '' : datum.SubCategory"},
      "fontSize": {"signal": "max(9, min(14, datum.r / 4))"}
    }
  }
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": 5,
  "autosize": "none",
  "description": "Tableau-style packed bubbles: size = Sales by SubCategory, colour = Category",
  "data": [
    {"name": "dataset"},
    {
      "name": "agg",
      "source": "dataset",
      "transform": [{"type": "formula", "expr": "datum['Total Sales']", "as": "Sales"}]
    },
    {
      "name": "tree",
      "source": "agg",
      "transform": [
        {"type": "formula", "expr": "datum.SubCategory", "as": "id"},
        {"type": "formula", "expr": "'root'", "as": "parent"}
      ]
    },
    {"name": "rootNode", "values": [{"id": "root", "parent": null}]},
    {
      "name": "nodes",
      "source": ["rootNode", "tree"],
      "transform": [
        {"type": "stratify", "key": "id", "parentKey": "parent"},
        {
          "type": "pack",
          "field": "Sales",
          "sort": {"field": "value", "order": "descending"},
          "size": [{"signal": "width"}, {"signal": "height"}],
          "padding": 4
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "color",
      "type": "ordinal",
      "domain": {"data": "agg", "field": "Category"},
      "range": {"scheme": "tableau10"}
    }
  ],
  "legends": [{"fill": "color", "title": "Category", "orient": "top-left"}],
  "marks": [
    {
      "type": "symbol",
      "from": {"data": "nodes"},
      "encode": {
        "enter": {"shape": {"value": "circle"}},
        "update": {
          "x": {"field": "x"},
          "y": {"field": "y"},
          "size": {"signal": "4*datum.r*datum.r"},
          "fill": [
            {"test": "datum.id=='root'", "value": "transparent"},
            {"scale": "color", "field": "Category"}
          ],
          "stroke": [
            {
              "test": "datum.id=='rootNode'||datum.id=='root'",
              "value": "transparent"
            },
            {"value": "white"}
          ],
          "tooltip": {
            "signal": "datum.id=='root'?null:{SubCategory:datum.SubCategory,Sales:format(datum.Sales,',.0f')}"
          },
          "fillOpacity": {"signal": "datum.__selected__ == 'off' ? 0.3 : 1"}
        }
      }
    },
    {
      "type": "text",
      "from": {"data": "nodes"},
      "encode": {
        "update": {
          "x": {"field": "x"},
          "y": {"field": "y"},
          "align": {"value": "center"},
          "baseline": {"value": "middle"},
          "text": {"signal": "datum.id=='root'||datum.r<16?'':datum.SubCategory"},
          "fill": {"value": "white"},
          "fontSize": {"signal": "max(9,min(14,datum.r/4))"}
        }
      }
    }
  ],
  "background": "white"
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "data": [
    {"name": "dataset"},
    {
      "name": "leaf",
      "source": "dataset",
      "transform": [
        {
          "type": "formula",
          "expr": "datum.Category + '|' + datum.SubCategory",
          "as": "id"
        },
        {"type": "formula", "expr": "datum.Category", "as": "parent"}
      ]
    },
    {
      "name": "cats",
      "source": "dataset",
      "transform": [
        {"type": "aggregate", "groupby": ["Category"]},
        {"type": "formula", "expr": "datum.Category", "as": "id"},
        {"type": "formula", "expr": "'root'", "as": "parent"}
      ]
    },
    {"name": "rootNode", "values": [{"id": "root", "parent": null}]},
    {
      "name": "tree",
      "source": ["rootNode", "cats", "leaf"],
      "transform": [
        {"type": "stratify", "key": "id", "parentKey": "parent"},
        {
          "type": "treemap",
          "field": "Total Sales",
          "method": "squarify",
          "round": true,
          "size": [{"signal": "width"}, {"signal": "height"}],
          "paddingInner": 2
        }
      ]
    },
    {
      "name": "leaves",
      "source": "tree",
      "transform": [{"type": "filter", "expr": "datum.SubCategory"}]
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {"data": "leaves"},
      "encode": {
        "update": {
          "x": {"field": "x0"},
          "y": {"field": "y0"},
          "x2": {"field": "x1"},
          "y2": {"field": "y1"},
          "fill": {"value": "#4e79a7"},
          "stroke": {"value": "white"}
        }
      }
    }
  ]
}

[
  {
