          "fields": ["DestLon", "DestLat"],
          "as": ["x2", "y2"]
        }
      ]
    },
    {
      "name": "kpi",
      "source": "airports",
      "transform": [
        {
          "type": "aggregate",
          "fields": ["code", "n"],
          "ops": ["count", "sum"],
          "as": ["airports", "ends"]
        }
      ]
    },
    {
      "name": "kpi2",
      "source": "dataset",
      "transform": [
        {
          "type": "aggregate",
          "fields": ["Cancelled", "Cancelled"],
          "ops": ["count", "sum"],
          "as": ["routes", "total"]
        }
      ]
    }
  ],
  "projections": [
    {
      "name": "proj",
      "type": "albersUsa",
      "fit": {"signal": "data('states')"},
      "extent": {"signal": "[[20, top], [width - 20, height - 10]]"}
    }
  ],
  "scales": [
    {
      "name": "size",
      "type": "linear",
      "domain": {"data": "airports", "field": "n"},
      "zero": true,
      "range": [0, 4200]
    }
  ],
  "marks": [
    {
      "type": "shape",
      "from": {"data": "states"},
      "encode": {
        "enter": {
          "fill": {"value": "#e4e4e4"},
          "stroke": {"value": "white"},
          "strokeWidth": {"value": 1}
        }
      },
      "transform": [{"type": "geoshape", "projection": "proj"}]
    },
    {
      "type": "rule",
      "from": {"data": "routes"},
      "encode": {
        "update": {
          "x": {"field": "x1"},
          "y": {"field": "y1"},
          "x2": {"field": "x2"},
          "y2": {"field": "y2"},
          "stroke": {"value": "#7d7d7d"},
          "strokeOpacity": {"value": 0.3},
          "strokeWidth": {"value": 0.7}
        }
      }
    },
    {
      "type": "symbol",
      "name": "dots",
      "from": {"data": "airports"},
      "encode": {
        "update": {
          "x": {"field": "x"},
          "y": {"field": "y"},
          "size": {"scale": "size", "field": "n"},
          "fill": {"value": "#f4b46a"},
          "fillOpacity": {"value": 0.55},
          "stroke": [{"test": "datum.rank <= 7", "value": "#111"}, {"value": "#e8892c"}],
          "strokeWidth": [{"test": "datum.rank <= 7", "value": 2}, {"value": 0.8}],
          "tooltip": {"signal": "{'Airport': datum.name, 'Cancelled': datum.n}"}
        }
      }
    },
    {
      "type": "text",
      "from": {"data": "airports"},
      "encode": {
        "update": {
          "x": {"field": "x"},
          "y": {"signal": "datum.y + sqrt(scale('size', datum.n) / PI) + 11"},
          "text": {"signal": "datum.rank <= 7 ? datum.name : ''"},
          "align": {"value": "center"},
          "font": {"value": "Segoe UI"},
          "fontWeight": {"value": "bold"},
          "fontSize": {"value": 12},
          "fill": {"value": "#111"},
