        "update": {
          "x": {"field": "x"},
          "y": {"signal": "datum.y + sqrt(scale('size', datum.n) / PI) + 25"},
          "text": {"signal": "datum.rank <= 7 ? datum.n : ''"},
          "align": {"value": "center"},
          "font": {"value": "Segoe UI"},
          "fontSize": {"value": 12},
          "fill": {"value": "#333"}
        }
      }
    },
    {
