              "fontWeight": {"value": "bold"},
              "font": {"value": "Segoe UI"},
              "text": {"field": "airports"}
            }
          }
        }
      ]
    },
    {
      "type": "group",
      "from": {"data": "kpi2"},
      "marks": [
        {
          "type": "text",
          "from": {"data": "kpi2"},
          "encode": {
