            }
          }
        },
        {
          "type": "text",
          "from": {"data": "kpi2"},
          "encode": {
            "update": {
              "x": {"signal": "width * 0.5"},
              "y": {"value": 52},
              "align": {"value": "center"},
              "fontSize": {"value": 32},
              "fontWeight": {"value": "bold"},
              "font": {"value": "Segoe UI"},
              "text": {"field": "routes"}
            }
          }
        },
        {
          "type": "text",
          "from": {"data": "kpi2"},
          "encode": {
            "update": {
              "x": {"signal": "width * 0.67"},
              "y": {"value": 14},
              "align": {"value": "center"},
              "fontSize": {"value": 11},
